mapper.update:
update abr_consultant
set countries = cast(#{countries} as jsonb), degrees = cast(#{degrees} as jsonb), max_active = #{maxActive}, accepting = #{accepting},
    update_by = #{updateBy}, update_time = now(), remark = #{remark}
where consultant_id = #{consultantId}

update abr_staff_notice set read_flag = 'Y', read_time = now()
where user_id = #{userId} and read_flag = 'N'

  and notice_id in #{id}
